package lending.model;

public record LoanApplication(
        String id,
        String applicantName,
        String ssn,
        String dateOfBirth,
        long amountCents) {

    public String maskedSsn() {
        if (ssn == null || ssn.length() < 4) {
            return "***";
        }
        return "***-**-" + ssn.substring(ssn.length() - 4);
    }

    @Override
    public String toString() {
        return "LoanApplication[id=" + id + ", applicantName=" + applicantName
                + ", ssn=" + maskedSsn() + ", amountCents=" + amountCents + "]";
    }

    public boolean exceeds(long limitCents) {
        return amountCents > limitCents;
    }
}
